private function filterAddress(string $remoteAddress)
{
    if (strpos($remoteAddress, ',') !== false) {
        $ipList = explode(',', $remoteAddress);
    } else {
        $ipList = [$remoteAddress];
    }
    $ipList = array_filter(
        $ipList,
        function (string $ip) {
            return filter_var(trim($ip), FILTER_VALIDATE_IP);
        }
    );
    if ($this->trustedProxies !== null) {
        $ipList = array_filter(
            $ipList,
